-- Atelier Lagos (Fashion)
-- Generated by gen_datasets.py with a fixed seed. Fictional data.

DROP TABLE IF EXISTS returns; DROP TABLE IF EXISTS sale_lines; DROP TABLE IF EXISTS sales; DROP TABLE IF EXISTS customers;
DROP TABLE IF EXISTS staff; DROP TABLE IF EXISTS stores; DROP TABLE IF EXISTS products; DROP TABLE IF EXISTS collections; DROP TABLE IF EXISTS brands;
CREATE TABLE brands (brand_id INT PRIMARY KEY, brand_name VARCHAR(60) COLLATE NOCASE NOT NULL, country VARCHAR(60) COLLATE NOCASE, founded_year INT);
CREATE TABLE collections (collection_id INT PRIMARY KEY, brand_id INT REFERENCES brands(brand_id), collection_name VARCHAR(60) COLLATE NOCASE, season VARCHAR(4) COLLATE NOCASE, launch_date DATE);
CREATE TABLE products (product_id INT PRIMARY KEY, sku VARCHAR(10) COLLATE NOCASE, collection_id INT REFERENCES collections(collection_id), product_name VARCHAR(60) COLLATE NOCASE,
  category VARCHAR(60) COLLATE NOCASE, cost_price DECIMAL(10,2), retail_price DECIMAL(10,2));
CREATE TABLE stores (store_id INT PRIMARY KEY, store_name VARCHAR(60) COLLATE NOCASE, city VARCHAR(60) COLLATE NOCASE, country VARCHAR(60) COLLATE NOCASE, opened_date DATE);
CREATE TABLE staff (staff_id INT PRIMARY KEY, store_id INT REFERENCES stores(store_id), first_name VARCHAR(60) COLLATE NOCASE, last_name VARCHAR(60) COLLATE NOCASE, role VARCHAR(60) COLLATE NOCASE,
  manager_id INT REFERENCES staff(staff_id), hire_date DATE, salary DECIMAL(10,2));
CREATE TABLE customers (customer_id INT PRIMARY KEY, first_name VARCHAR(60) COLLATE NOCASE, last_name VARCHAR(60) COLLATE NOCASE, email VARCHAR(60) COLLATE NOCASE, city VARCHAR(60) COLLATE NOCASE, join_date DATE, loyalty_tier VARCHAR(60) COLLATE NOCASE);
CREATE TABLE sales (sale_id INT PRIMARY KEY, store_id INT REFERENCES stores(store_id), staff_id INT REFERENCES staff(staff_id),
  customer_id INT REFERENCES customers(customer_id), sale_date DATE, channel VARCHAR(60) COLLATE NOCASE);
CREATE TABLE sale_lines (line_id INT PRIMARY KEY, sale_id INT REFERENCES sales(sale_id), product_id INT REFERENCES products(product_id), qty INT,
  unit_price DECIMAL(10,2), discount DECIMAL(4,2));
CREATE TABLE returns (return_id INT PRIMARY KEY, line_id INT REFERENCES sale_lines(line_id), return_date DATE, reason VARCHAR(60) COLLATE NOCASE);










-- Raw sign-up import for Module 13 (Data Cleaning). Deliberately messy.
DROP TABLE IF EXISTS newsletter_signups;
CREATE TABLE newsletter_signups (signup_id INT PRIMARY KEY, full_name VARCHAR(60) COLLATE NOCASE, email VARCHAR(60) COLLATE NOCASE, phone VARCHAR(20), preferred_store VARCHAR(60) COLLATE NOCASE,
  signup_date VARCHAR(10), source VARCHAR(60) COLLATE NOCASE, first_order_value VARCHAR(20));
